import { EventEmitter } from 'events';

interface FeatureFlag {
  name: string;
  enabled: boolean;
  metadata?: Record<string, unknown>;
}

interface QueueMessage {
  id: string;
  topic: string;
  payload: Record<string, unknown>;
  headers: Record<string, string>;
  timestamp: number;
}

interface ConsumerConfig {
  groupId: string;
  topics: string[];
  featureFlags: FeatureFlag[];
  overrides?: Record<string, unknown>;
}

class FeatureFlagStore {
  private flags: Map<string, FeatureFlag> = new Map();
  private configCache: object = {};

  loadFlags(flags: FeatureFlag[]): void {
    for (const flag of flags) {
      this.flags.set(flag.name, flag);
    }
  }

  isEnabled(name: string): boolean {
    return this.flags.get(name)?.enabled ?? false;
  }

  applyOverrides(overrides: Record<string, unknown>): void {
    this.mergeDeep(this.configCache, overrides);
  }

  private mergeDeep(target: any, source: any): any {
    const output = target;
    if (this.isObject(target) && this.isObject(source)) {
      for (const key of Object.keys(source)) {
        if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
          continue;
        }
        if (this.isObject(source[key])) {
          if (!(key in target)) {
            Object.assign(output, { [key]: {} });
          }
          this.mergeDeep(output[key], source[key]);
        } else {
          Object.assign(output, { [key]: source[key] });
        }
      }
    }
    return output;
  }

  private isObject(item: unknown): item is Record<string, unknown> {
    return item !== null && typeof item === 'object' && !Array.isArray(item);
  }

  getConfig(): object {
    return { ...this.configCache };
  }
}

class MessageProcessor {
  private emitter: EventEmitter;
  private flagStore: FeatureFlagStore;

  constructor(flagStore: FeatureFlagStore) {
    this.emitter = new EventEmitter();
    this.flagStore = flagStore;
  }

  async processMessage(message: QueueMessage): Promise<void> {
    if (!this.flagStore.isEnabled('message_processing_v2')) {
      return this.processLegacy(message);
    }

    const enriched = this.enrichPayload(message);
    this.emitter.emit('processed', enriched);
  }

  private enrichPayload(message: QueueMessage): QueueMessage {
    return {
      ...message,
      payload: {
        ...message.payload,
        processedAt: Date.now(),
        version: 2
      }
    };
  }

  private processLegacy(message: QueueMessage): void {
    this.emitter.emit('processed', message);
  }

  onProcessed(handler: (msg: QueueMessage) => void): void {
    this.emitter.on('processed', handler);
  }
}

class QueueConsumer {
  private config: ConsumerConfig;
  private processor: MessageProcessor;
  private flagStore: FeatureFlagStore;
  private running: boolean = false;

  constructor(config: ConsumerConfig) {
    this.config = config;
    this.flagStore = new FeatureFlagStore();
    this.flagStore.loadFlags(config.featureFlags);
    this.processor = new MessageProcessor(this.flagStore);
  }

  async initialize(): Promise<void> {
    if (this.config.overrides) {
      this.flagStore.applyOverrides(this.config.overrides);
    }
    this.running = true;
  }

  async consumeMessage(raw: string): Promise<void> {
    if (!this.running) {
      throw new Error('Consumer not initialized');
    }

    const message: QueueMessage = JSON.parse(raw);

    if (!this.config.topics.includes(message.topic)) {
      return;
    }

    if (message.headers && message.headers['x-feature-overrides']) {
      const dynamicOverrides = JSON.parse(message.headers['x-feature-overrides']);
      this.flagStore.applyOverrides(dynamicOverrides);
    }

    await this.processor.processMessage(message);
  }

  getProcessor(): MessageProcessor {
    return this.processor;
  }
}

export { QueueConsumer, ConsumerConfig, QueueMessage, FeatureFlag };
